package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks for on a sheet: any request on a sheet other than a read is refused before
 * it reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (which a viewer takes with
 * every selected item refused) are left to their handlers; see {@link ViewerGuardConfig}.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    private final RoleService roles;

    public ViewerGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || sheetId == null) {
            return true;
        }
        if (roles.isViewer(sheetId, user.trim())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything on this sheet");
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) {
            return null;
        }
        Map<String, String> path = (Map<String, String>) map;
        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
    }
}
package net.officefloor.hq.app.role;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/** Puts the {@link ViewerGuard} in front of a sheet's API, except loading it and its bulk actions. */
@Configuration
public class ViewerGuardConfig implements WebMvcConfigurer {

    private final ViewerGuard guard;

    public ViewerGuardConfig(ViewerGuard guard) {
        this.guard = guard;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(guard)
                .addPathPatterns("/api/sheets/**")
                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*");
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles a sheet's settings assign to user names. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Delegations delegations;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, SheetRepository sheetStore, Delegations delegations,
            Audit audit) {
        this.roles = roles;
        this.delegations = delegations;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The role a user name acts in on the sheet: steward while a delegation of the role to it holds the sheet's
     *  today, else the one assigned. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        if (delegations.actingFor(sheetId, userName).isPresent()) {
            return Role.STEWARD;
        }
        return assignedRoleOf(sheetId, userName);
    }

    /** The role assigned to a user name on the sheet, else clerk; a delegation does not change it. */
    @Transactional(readOnly = true)
    public String assignedRoleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** Whether a user name is a viewer on the sheet: one who sees everything and can change nothing. */
    @Transactional(readOnly = true)
    public boolean isViewer(String sheetId, String userName) {
        return Role.VIEWER.equals(roleOf(sheetId, userName));
    }

    /** Assign a role (clerk, steward or viewer) to a user name, replacing the one it had. The sheet is locked
     *  first, so two assignments to one name are made one at a time. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Role row = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        row.setRole(role);
        Role saved = roles.saveAndFlush(row);
        audit.recordChangeOnCommit(sheetId, user, "ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
