    /** A sheet as the screen shows it, each dated setting as it is in force on the sheet's today, with every dated value
     *  recorded; the clerk limit (null: no limit) and floor and late percent have exactly two decimals; terms is in days;
     *  the policy date is null when it is the sheet's today; the period numbering from is null when it is off; the cap (two decimals) is null when there is none, as is the proof threshold (two decimals); the permissions are the
     *  matrix entries set, by action (one missing keeps its standing rule); the grace days are null when off. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<DatedSettingView> settings, String proofThreshold, Map<String, String> permissions, Integer graceDays) {

        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(s -> new DatedSettingView(s.getKey(), s.getFrom(), s.getValue())).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions(), sheet.getGraceDays());
        }
    }

    /** A dated setting's value from a from-date (null: from the beginning of time); a null value means none. */
    public record DatedSettingView(String key, LocalDate from, String value) {
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    /** The sheet's settings as the form submits them; a missing clerk limit means no limit, a missing from-date the sheet's today. */
    public record SettingsChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal clerkLimit, LocalDate from) {
    }

    /** The sheet's floor as the form submits it. */
    public record FloorChange(@NotNull @DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal floor, LocalDate from) {
    }

    /** The sheet's terms, in days, as the form submits them. */
    public record TermsChange(@NotNull @Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** A grade's own terms, in days, as the form submits them; missing ones leave the grade on the sheet's terms. */
    public record GradeTermsChange(@Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** The sheet's late percent as the form submits it. */
    public record LatePctChange(@NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal latePct, LocalDate from) {
    }

    /** The sheet's policy date as the form submits it; a missing one means the sheet's today. */
    public record PolicyDateChange(LocalDate policyDate) {
    }

    /** The sheet's period numbering from as the form submits it; a missing one means off. */
    public record PeriodNumberingFromChange(LocalDate periodNumberingFrom) {
    }

    /** The sheet's grace days as the form submits them; missing ones mean off. */
    public record GraceDaysChange(@Min(0) @Max(36500) Integer graceDays) {
    }

    /** The sheet's cap as the form submits it; a missing one means none. */
    public record CapChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal cap, LocalDate from) {
    }

    /** The sheet's proof threshold as the form submits it; a missing one means none. */
    public record ProofThresholdChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal proofThreshold, LocalDate from) {
    }

    /** The roles that may take an action as the form submits them, comma separated; blank keeps the standing rule. */
    public record PermissionChange(@Size(max = 100) String roles) {
    }

    private final SheetService sheets;

    public SheetController(SheetService sheets) {
        this.sheets = sheets;
    }

    /** Load (re-read) a sheet by id, starting it empty if it has never been loaded. */
    @PostMapping("/{id}/load")
    public SheetView load(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(sheets.load(id, user));
    }

    /** Change the sheet's today (an ISO date). */
    @PutMapping("/{id}/today")
    public SheetView setToday(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TodayChange request) {
        return SheetView.of(sheets.setToday(id, user, request.today()));
    }

    /** Change the sheet's settings. */
    @PutMapping("/{id}/settings")
    public SheetView setSettings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody SettingsChange request) {
        return SheetView.of(sheets.setClerkLimit(id, user, request.clerkLimit(), request.from()));
    }

    /** Change the sheet's floor. */
    @PutMapping("/{id}/settings/floor")
    public SheetView setFloor(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody FloorChange request) {
        return SheetView.of(sheets.setFloor(id, user, request.floor(), request.from()));
    }

    /** Change the sheet's terms. */
    @PutMapping("/{id}/settings/terms")
    public SheetView setTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TermsChange request) {
        return SheetView.of(sheets.setTerms(id, user, request.terms(), request.from()));
    }

    /** Change a grade's own terms. */
    @PutMapping("/{id}/settings/terms/{grade}")
    public SheetView setGradeTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GradeTermsChange request) {
        return SheetView.of(sheets.setGradeTerms(id, user, grade, request.terms(), request.from()));
    }

    /** Change the sheet's late percent. */
    @PutMapping("/{id}/settings/late-pct")
    public SheetView setLatePct(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LatePctChange request) {
        return SheetView.of(sheets.setLatePct(id, user, request.latePct(), request.from()));
    }

    /** Change the sheet's policy date. */
    @PutMapping("/{id}/settings/policy-date")
    public SheetView setPolicyDate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PolicyDateChange request) {
        return SheetView.of(sheets.setPolicyDate(id, user, request.policyDate()));
    }

    /** Change the sheet's period numbering from. */
    @PutMapping("/{id}/settings/period-numbering-from")
    public SheetView setPeriodNumberingFrom(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodNumberingFromChange request) {
        return SheetView.of(sheets.setPeriodNumberingFrom(id, user, request.periodNumberingFrom()));
    }

    /** Change the sheet's grace days. */
    @PutMapping("/{id}/settings/grace-days")
    public SheetView setGraceDays(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GraceDaysChange request) {
        return SheetView.of(sheets.setGraceDays(id, user, request.graceDays()));
    }

    /** Change the sheet's cap. */
    @PutMapping("/{id}/settings/cap")
    public SheetView setCap(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody CapChange request) {
        return SheetView.of(sheets.setCap(id, user, request.cap(), request.from()));
    }

    /** Change the sheet's proof threshold. */
    @PutMapping("/{id}/settings/proof-threshold")
    public SheetView setProofThreshold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ProofThresholdChange request) {
        return SheetView.of(sheets.setProofThreshold(id, user, request.proofThreshold(), request.from()));
    }

    /** Change the roles that may take an action. */
    @PutMapping("/{id}/settings/perm/{action}")
    public SheetView setPermission(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @PathVariable @Pattern(regexp = "open|settle|void|reassign|close|reopen") String action,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PermissionChange request) {
        return SheetView.of(sheets.setPermission(id, user, action, request.roles()));
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.annotation.Lazy;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Loads sheets by id; a sheet never loaded before is started empty. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Audit audit;

    private final PeriodService periods;

    // The period service loads sheets through this one, so it is taken lazily.
    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit, @Lazy PeriodService periods) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
        this.periods = periods;
    }

    /** The sheet with this id, re-read from the store; started empty if it has never been loaded. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                // Another user started the same sheet at the same moment: theirs stands.
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /** The sheet's today, or null for a sheet never loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElse(null);
    }

    /** Set the sheet's today, starting the sheet if it has never been loaded; then close every open period past its
     *  grace days. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = rollup.of(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        periods.closePastGrace(saved, user);
        rollup.recordChanges(id, user, before);
        return saved;
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), starting the sheet if
     *  it has never been loaded. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return record(id, user, Sheet.CLERK_LIMIT, from, limit == null ? null : scaled(limit), false);
    }

    /** Record the sheet's floor from a date (null: the sheet's today), starting the sheet if it has never been
     *  loaded. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        return record(id, user, Sheet.FLOOR, from, scaled(floor), true);
    }

    /** Record the sheet's terms in days from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return record(id, user, Sheet.TERMS, from, String.valueOf(terms), false);
    }

    /** Record a grade's own terms in days (null: the sheet's terms) from a date (null: the sheet's today), starting
     *  the sheet if it has never been loaded. */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return record(id, user, Sheet.TERMS + "-" + grade, from, terms == null ? null : String.valueOf(terms), false);
    }

    /** Record the sheet's late percent from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        return record(id, user, Sheet.LATE_PCT, from, scaled(latePct), true);
    }

    /** Set the sheet's policy date (null: the sheet's today), starting the sheet if it has never been loaded. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = rollup.of(id);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=policy-date value=" + (policyDate == null ? "" : policyDate));
        rollup.recordChanges(id, user, before);
        return saved;
    }

    /** Set the sheet's period numbering from (null: off), starting the sheet if it has never been loaded. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=period-numbering-from value=" + (from == null ? "" : from));
        return saved;
    }

    /** Set the sheet's grace days (null: off), starting the sheet if it has never been loaded. Not dated. */
    @Transactional
    public Sheet setGraceDays(String id, String user, Integer graceDays) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setGraceDays(graceDays);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=grace-days value=" + (graceDays == null ? "" : graceDays));
        return saved;
    }

    /** Record the sheet's cap (null: none) from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
        return record(id, user, Sheet.CAP, from, cap == null ? null : scaled(cap), true);
    }

    /** Record the sheet's proof threshold (null: none) from a date (null: the sheet's today), starting the sheet if
     *  it has never been loaded. */
    @Transactional
    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
        return record(id, user, Sheet.PROOF_THRESHOLD, from, threshold == null ? null : scaled(threshold), false);
    }

    /** Set the roles that may take an action (a comma separated list of clerk and steward; blank: its standing
     *  rule), starting the sheet if it has never been loaded. Not dated. Refused for a role that is neither. */
    @Transactional
    public Sheet setPermission(String id, String user, String action, String roles) {
        List<String> listed = roles == null ? List.of()
                : Arrays.stream(roles.split(",")).map(String::trim).filter(r -> !r.isEmpty()).distinct().toList();
        if (listed.stream().anyMatch(r -> !Role.CLERK.equals(r) && !Role.STEWARD.equals(r))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A permission lists the roles clerk and steward");
        }
        String value = String.join(",", listed);
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setPermission(action, value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + value);
        return saved;
    }

    /** Record a dated setting's value (null: none) from a date (null: the sheet's today), replacing the one it had
     *  from that date; the audit line ends with the from-date when one was given. A setting a claim's due depends on
     *  records how the figures moved. */
    private Sheet record(String id, String user, String key, LocalDate from, String value, boolean movesFigures) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = movesFigures ? rollup.of(id) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key
                + " value=" + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollup.recordChanges(id, user, before);
        }
        return saved;
    }

    private static String scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}

